# 运维脚本：从受信任的配置源读取服务名，执行健康检查并上报指标
import os
import subprocess
import json
import shlex
from pathlib import Path

ALLOWED_SERVICES = {"api-gateway", "auth-service", "payment-service", "inventory-service"}

def load_service_config(config_path: str) -> dict:
    """从受信任的配置文件加载服务列表（只读，不可被外部写入）"""
    config_file = Path(config_path)
    if not config_file.exists() or config_file.stat().st_mode & 0o022:
        raise ValueError("Config file must be read-only and exist")
    with open(config_file, "r") as f:
        return json.load(f)

def run_health_check(service_name: str) -> dict:
    """执行健康检查命令，返回状态和耗时"""
    # 安全点 1：白名单校验 —— 只允许预定义的服务名
    if service_name not in ALLOWED_SERVICES:
        raise ValueError(f"Service {service_name} not in allowed list")

    # 安全点 2：使用列表参数 + shell=False，避免任何 shell 解释
    cmd = ["/usr/bin/curl", "-sf", f"http://{service_name}:8080/health"]
    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, timeout=10, shell=False
        )
        return {
            "service": service_name,
            "healthy": result.returncode == 0,
            "output": result.stdout[:200]  # 截断输出，防止日志注入
        }
    except subprocess.TimeoutExpired:
        return {"service": service_name, "healthy": False, "output": "timeout"}

def main(config_path: str):
    config = load_service_config(config_path)
    services = config.get("services", [])

    # 安全点 3：即使 config 被篡改，白名单 + 列表参数形成双重防线
    for svc in services:
        if not isinstance(svc, str):
            continue
        result = run_health_check(svc)
        # 安全点 4：格式化字符串用于日志，但参数已通过白名单，无注入面
        print(f"[deploy] {result['service']}: healthy={result['healthy']}")

    # 安全点 5：不使用 os.system / shell=True / 字符串拼接
    # 全脚本无一处将用户输入拼接到 shell 命令中

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        sys.exit("Usage: deploy_metrics.py <config_path>")
    main(sys.argv[1])

