#define MAX_BUF_LEN 128

struct device_ctx {
    char *buffer;
    size_t len;
    struct mutex lock;
};

static struct device_ctx *ctx;

static void ctx_cleanup(struct device_ctx *dev)
{
    if (!dev)
        return;
    mutex_lock(&dev->lock);
    if (dev->buffer) {
        kfree(dev->buffer);
        dev->buffer = NULL;  /* line 18: NULL after free */
    }
    mutex_unlock(&dev->lock);
}

static ssize_t dev_write(struct device *dev, struct device_attribute *attr,
                         const char *buf, size_t count)
{
    struct device_ctx *d = ctx;
    char *new_buf;
    size_t new_len;

    if (count > MAX_BUF_LEN)
        return -EINVAL;

    mutex_lock(&d->lock);
    if (!d->buffer) {
        mutex_unlock(&d->lock);
        return -ENODEV;
    }

    new_len = count;
    new_buf = kmemdup(buf, new_len, GFP_KERNEL);
    if (!new_buf) {
        mutex_unlock(&d->lock);
        return -ENOMEM;
    }

    kfree(d->buffer);          /* line 36: old buffer freed */
    d->buffer = new_buf;       /* line 37: pointer updated atomically */
    d->len = new_len;
    mutex_unlock(&d->lock);
    return count;
}

static ssize_t dev_read(struct device *dev, struct device_attribute *attr,
                        char *buf)
{
    struct device_ctx *d = ctx;
    int ret;

    mutex_lock(&d->lock);
    if (!d->buffer) {
        mutex_unlock(&d->lock);
        return -ENODEV;
    }
    ret = snprintf(buf, d->len + 1, "%s", d->buffer); /* line 51: bounded copy */
    mutex_unlock(&d->lock);
    return ret;
}

static int __init probe(void)
{
    ctx = kzalloc(sizeof(*ctx), GFP_KERNEL);
    if (!ctx)
        return -ENOMEM;
    mutex_init(&ctx->lock);
    ctx->buffer = kzalloc(MAX_BUF_LEN, GFP_KERNEL);
    if (!ctx->buffer) {
        kfree(ctx);
        return -ENOMEM;
    }
    ctx->len = MAX_BUF_LEN;
    return 0;
}

static void __exit remove_dev(void)
{
    ctx_cleanup(ctx);
    kfree(ctx);
}

// 基于 Flask 框架的用户认证模块（使用 Java 模拟，实际为 Flask 路由）
// 文件: auth_service.py

from flask import Flask, request, jsonify, session
from werkzeug.security import check_password_hash
import re

app = Flask(__name__)
app.secret_key = "a-very-secure-random-secret-key-2024"

# 模拟用户数据库（实际应为数据库查询）
USERS = {
    "alice": {"password_hash": "pbkdf2:sha256:260000$abc123", "role": "admin"},
    "bob": {"password_hash": "pbkdf2:sha256:260000$def456", "role": "user"}
}

@app.route("/login", methods=["POST"])
def login():
    """用户登录接口"""
    data = request.get_json()
    username = data.get("username", "")
    password = data.get("password", "")

    # 防御层1: 白名单校验用户名，仅允许字母数字和下划线
    if not re.match(r"^[a-zA-Z0-9_]+$", username):
        return jsonify({"error": "invalid_username"}), 400

    # 防御层2: 密码长度限制，防止超长输入导致哈希计算 DoS
    if len(password) > 128:
        return jsonify({"error": "password_too_long"}), 400

    # 防御层3: 从预定义字典查询，而非拼接 SQL
    user_record = USERS.get(username)
    if user_record is None:
        return jsonify({"error": "invalid_credentials"}), 401

    # 防御层4: 使用 werkzeug 的安全哈希比对，避免时序攻击
    if not check_password_hash(user_record["password_hash"], password):
        return jsonify({"error": "invalid_credentials"}), 401

    # 防御层5: 会话固定防护——登录成功后重新生成 session ID
    session.clear()
    session["username"] = username
    session["role"] = user_record["role"]

    return jsonify({"message": "login_success", "role": user_record["role"]}), 200

@app.route("/profile", methods=["GET"])
def profile():
    """获取当前用户信息"""
    # 防御层6: 会话中获取用户名，而非从请求参数读取
    username = session.get("username")
    if username is None:
        return jsonify({"error": "unauthorized"}), 401

    # 防御层7: 再次校验，防止会话被篡改后注入
    if not re.match(r"^[a-zA-Z0-9_]+$", username):
        session.clear()
        return jsonify({"error": "session_invalid"}), 403

    # 防御层8: 仅返回白名单字段，避免信息泄露
    user_record = USERS.get(username)
    if user_record is None:
        session.clear()
        return jsonify({"error": "user_not_found"}), 404

    return jsonify({"username": username, "role": user_record["role"]}), 200

if __name__ == "__main__":
    app.run(debug=False)  # 生产环境禁用 debug
